void Solver::bump_var(int var, double coeff) {
    // compile‑time constants, no reallocation on each call
    static const double ACT_LIMIT   = 1e100;
    static const double RESCALE_FAC = 1e-100;

    // increase activity
    activity[var] += var_inc * coeff;

    // if any activity exceeds the safe limit, rescale everything once
    if (activity[var] > ACT_LIMIT) {
        for (int i = 1; i <= vars; ++i) activity[i] *= RESCALE_FAC;
        var_inc *= RESCALE_FAC;
    }

    // keep the VSIDS heap consistent
    if (vsids.inHeap(var)) vsids.update(var);
}
